import { NextResponse } from 'next/server'

interface PostRequestBody {
  title?: string
  content?: string
}

export async function GET() {
  // Simulate fetching posts
  const posts = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts, { status: 200 })
}

export async function POST(request: Request) {
  const { title, content }: PostRequestBody = await request.json()

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextResponse } from 'next/server'

interface RouteContext {
  params: Promise<{ id: string }>
}

interface PostRequestBody {
  title?: string
  content?: string
}

export async function GET(_request: Request, { params }: RouteContext) {
  const { id } = await params

  // Simulate fetching a single post
  const post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(request: Request, { params }: RouteContext) {
  const { id } = await params
  const { title, content }: PostRequestBody = await request.json()

  // Simulate updating a post
  const updatedPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(_request: Request, { params }: RouteContext) {
  const { id } = await params

  // Simulate deleting a post
  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

